$(document).ready(function(a){getUserRequest("pc_newsList_01");document.title="新闻动态_招商财富 公司新闻、公司动态、新闻资讯、招商财富动态";$(".nav.fr ul li a").removeClass("current").eq(5).addClass("current");queryBondInvestorArticleNum("1");queryBondInvestorList();$(".information-left ul li a").removeClass("act");$(".information-left ul li.newnotice a").addClass("act")});function searchByName(){$(".information-left ul li").each(function(){if($(this).find("a").hasClass("act")){var a=$(this).index();if(a=="0"){queryBondInvestorArticle("1")}}})}function queryBondInvestorList(){getUserRequest("pc_publicityList_01");queryBondInvestorArticle("1")}function queryBondInvestorArticleNum(a){var b=$("#name").val();var c=returnPage(a);$.ajax({async:true,url:"/AppService/article/queryBondInvestorArticle.xhtml",data:{page:c,name:encodeURI(b)},dataType:"json",cache:false,type:"post",error:function(e,d){},success:function(d){if(d.list==null||d.list.length<=0){return}}})}function queryBondInvestorArticle(a){var b=$("#name").val();var c=returnPage(a);$.ajax({async:true,url:"/AppService/article/queryBondInvestorArticle.xhtml",data:{page:c,name:encodeURI(b)},dataType:"json",cache:false,type:"post",error:function(e,d){},success:function(i){var g="";var e="";if(i.list!=null&&i.list.length>0){$.each(i.list,function(j,k){g+="<dl>";g+="<h3 class='cursor' onclick='openToUrl(\"/AppService/article/newsDetail.shtml?articleId="+k.articleId+"&type=publicity\")'>"+k.title+"</h3>";g+="<dt>"+formatDate(k.publishDate)+"</dt>";g+="<dd>"+k.brief+"</dd>";g+="</dl>"});var h=i.currentPage;var f=i.count;var d=i.maxPages;$("#page").val(h);$("#maxPages").val(d);e+="<a href='javascript:queryBondInvestorArticle(\""+(h-1)+"\")' class='pre'></a>";if(h==1){e+="<a class='act' href='javascript:queryBondInvestorArticle(\"1\")'>1</a>"}else{e+="<a href='javascript:queryBondInvestorArticle(\"1\")'>1</a>"}if(h>3){e+="<a class='omit'></a>"}if((h-1)>1){e+="<a href='javascript:queryBondInvestorArticle(\""+(h-1)+"\")'>"+(h-1)+"</a>"}if(h!=1&&h!=d){e+="<a class='act' href='javascript:queryBondInvestorArticle(\""+(h)+"\")'>"+(h)+"</a>"}if(h+1<d){e+="<a href='javascript:queryBondInvestorArticle(\""+(h+1)+"\")'>"+(h+1)+"</a>"}if((d-h)>2){e+="<a class='omit'></a>"}if(h!=1){if(d==h){e+="<a class='act' href='javascript:queryBondInvestorArticle(\""+(d)+"\")'>"+d+"</a>"}else{if(d>h){e+="<a href='javascript:queryBondInvestorArticle(\""+(d)+"\")'>"+d+"</a>"}}}else{if(d==h){}else{if(d>h){e+="<a href='javascript:queryBondInvestorArticle(\""+(d)+"\")'>"+d+"</a>"}}}e+="<a href='javascript:queryBondInvestorArticle(\""+(h+1)+"\")' class='next'></a>";e+="</div>";$("#list").html(g);$(".page").html(e);$(".listNone").hide()}else{$("#list").html(g);$(".page").html(e);$(".listNone").show()}}})}function returnPage(a){var c;var b=$("#maxPages").val();if(parseInt(a,10)>=parseInt(b,10)){c=b}else{if(parseInt(a,10)<=0){c="1"}else{c=a}}return c};